// Pure business logic shared by n8n Code nodes and regression tests.
// All supplier data are synthetic. No external booking or money movement.
const clone = x => JSON.parse(JSON.stringify(x));
const iso = d => new Date(d).toISOString().slice(0,10);
const allowedPatch = ['origin','destination','start_date','end_date','adults','budget_total','currency','contact','hotel_stars','pace','interests','guide_language','must_have','avoid'];
const required = ['origin','destination','start_date','end_date','adults','budget_total','currency','contact'];
const interview = ['hotel_stars','pace','interests','guide_language'];
const events = ['request','approve','travellers','ack_documents','start_trip','end_trip','feedback','incident','resolve_incident','resolve_claim','question'];
const labels = {origin:'город отправления',destination:'направление',start_date:'дата начала YYYY-MM-DD',end_date:'дата окончания YYYY-MM-DD',adults:'число взрослых',budget_total:'общий бюджет на всю группу',currency:'валюта',contact:'контакт',hotel_stars:'категория отеля: 3 или 5',pace:'темп: relaxed или standard',interests:'интересы: museums и/или architecture',guide_language:'язык гида: ru или en'};
function initial(id, now) { return {session_id:id,request_id:'REQ-'+id,status:'NEW',brief:{},revision:0,proposal_version:0,proposals:[],incidents:[],claims:[],audit:[],created_at:now,clarification_rounds:0}; }
function context(input, old, now='2026-10-09T09:00:00.000Z') {
  const e=clone(input), s=old?clone(old):initial(e.session_id,now);
  return {e,s,now,halt:false,planning:false,trace:[],response:{},http_status:200};
}
function say(c,status,message,extra={}) {c.s.status=status;c.response={status,message,...extra};}
function stop(c,status,message,extra={}) {say(c,status,message,extra);c.halt=true;return c;}
function reject(c,message){c.http_status=400;c.response={status:'INVALID_EVENT',message,current_status:c.s.status};c.halt=true;return c;}
function trace(c,stage,action){c.trace.push({stage,action});}
function ask(c,status,message,extra={}) {
  c.s.clarification_rounds++;
  if(c.s.clarification_rounds>3) return stop(c,'MANAGER_REVIEW','Более трёх циклов уточнения. Требуется менеджер.',{reason:message,...extra});
  return stop(c,status,message,extra);
}
function validDate(x){return typeof x==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x)&&Number.isFinite(Date.parse(x))&&iso(x)===x;}
function days(b){return Math.round((Date.parse(b.end_date)-Date.parse(b.start_date))/86400000)+1;}
function quote(b,stars=b.hotel_stars){
  const nights=days(b)-1,rooms=Math.ceil(b.adults/2);
  const lines=[{id:'transport',unit:4000,quantity:b.adults,unit_basis:'round trip / adult'},
    {id:'hotel',unit:stars===5?15000:4000,quantity:nights*rooms,unit_basis:'room-night'},
    {id:'activities',unit:1200,quantity:b.adults*2,unit_basis:'visit / adult'},
    {id:'transfers',unit:1000,quantity:2,unit_basis:'group transfer'},
    {id:'guide',unit:3000,quantity:1,unit_basis:'group session'}];
  lines.forEach(x=>x.total=x.unit*x.quantity);
  const cost=lines.reduce((a,x)=>a+x.total,0),reserve=Math.round(cost*.05),markup=Math.round(cost*.15);
  return {mock:true,currency:'RUB',lines,cost,reserve,markup,total:cost+reserve+markup,estimated_profit:markup,margin_pct:100*markup/(cost+reserve+markup),rules:'reserve 5% of cost; markup 15% of cost; demo prices include supplier charges; no tax model'};
}
function validatePatch(p) {
  if(!p||typeof p!=='object'||Array.isArray(p))return 'patch phải là object';
  for(const [k,v] of Object.entries(p)){
    if(!allowedPatch.includes(k))return 'Unsupported field: '+k;
    if(v===null)continue; // Explicit null clears a previously known field.
    if(['adults','budget_total','hotel_stars'].includes(k)){if(typeof v!=='number'||!Number.isFinite(v))return 'Expected number: '+k;}
    else if(['interests','must_have','avoid'].includes(k)){if(!Array.isArray(v)||v.some(x=>typeof x!=='string'))return 'Expected string array: '+k;}
    else if(typeof v!=='string')return 'Expected string: '+k;
  }return null;
}
function sg1(c){
  if(c.halt)return c;
  trace(c,'SG1','register / merge explicit update');
  const {e,s}=c;
  if(!events.includes(e.event))return reject(c,'Неизвестное событие');
  if(e.event!=='request')return c;
  if(['WAITING_TRAVELLERS','AWAITING_DOCUMENT_RECEIPT','READY_FOR_TRIP','IN_TRIP','AWAITING_FEEDBACK','OPEN_CLAIM','CLOSED'].includes(s.status))return reject(c,'После согласования изменения обрабатывает менеджер.');
  const p=e.patch||{},err=validatePatch(p);if(err)return reject(c,err);
  s.brief={...s.brief,...p};s.revision++;c.planning=true;
  // Invalidate dependent artefacts whenever the brief changes.
  for(const k of ['proposal','approved_version','itinerary','services','visa','travel_pack','bookings','payment','documents','qa'])delete s[k];
  const missing=required.filter(k=>s.brief[k]===undefined||s.brief[k]===null||s.brief[k]==='');
  if(missing.length)return ask(c,'NEEDS_INFO','Уточните: '+missing.map(x=>labels[x]).join('; '),{missing_fields:missing});
  const b=s.brief,errors=[];
  if(!validDate(b.start_date)||!validDate(b.end_date))errors.push('Нужны действительные даты YYYY-MM-DD.');
  if(!Number.isInteger(b.adults)||b.adults<1)errors.push('Количество взрослых должно быть целым положительным числом.');
  if(!(b.budget_total>0))errors.push('Общий бюджет должен быть положительным.');
  if(!/^\S+@\S+\.\S+$/.test(b.contact)&&!/^\+?[0-9 ()-]{7,20}$/.test(b.contact))errors.push('Укажите e-mail или телефон.');
  if(errors.length)return ask(c,'NEEDS_INFO',errors.join(' '),{validation_errors:errors});
  return c;
}
function sg2(c){
  if(c.halt||!c.planning)return c;
  trace(c,'SG2','adaptive interview / requirement conflicts');
  const b=c.s.brief,missing=interview.filter(k=>b[k]===undefined||b[k]===null||b[k]===''||(Array.isArray(b[k])&&!b[k].length));
  if(missing.length)return ask(c,'NEEDS_PREFERENCES','Уточните предпочтения: '+missing.map(x=>labels[x]).join('; '),{missing_fields:missing});
  const conflicts=[];
  if(b.end_date<b.start_date)conflicts.push('Дата окончания раньше даты начала.');
  const opposite=(b.must_have||[]).filter(x=>(b.avoid||[]).map(x=>x.toLowerCase()).includes(x.toLowerCase()));
  if(opposite.length)conflicts.push('Одновременно обязательно и запрещено: '+opposite.join(', '));
  if(conflicts.length)return ask(c,'NEEDS_RESOLUTION',conflicts.join(' '),{conflicts,alternatives:['Исправьте противоречащие параметры. Обязательные требования не меняются автоматически.']});
  c.s.requirements={mandatory:{...clone(b)},negotiable:[],policy:'Only explicit client patch can change a requirement'};
  return c;
}
function sg3(c){
  if(c.halt||!c.planning)return c;
  trace(c,'SG3','feasibility / mock visa / daily schedule');
  const b=c.s.brief,n=days(b);
  if(b.start_date<c.now.slice(0,10))return ask(c,'NEEDS_RESOLUTION','Дата начала уже прошла. Укажите новые даты.');
  const unsupported=[];
  if(b.origin!=='Москва'||b.destination!=='Санкт-Петербург')unsupported.push('каталог MVP: Москва → Санкт-Петербург');
  if(n<2||n>7)unsupported.push('длительность MVP: 2–7 дней');
  if(b.adults>6)unsupported.push('группа MVP: 1–6 взрослых');
  if(b.currency!=='RUB')unsupported.push('валюта MVP: RUB');
  if(![3,5].includes(b.hotel_stars))unsupported.push('отели MVP: 3 или 5 звёзд');
  if(!['relaxed','standard'].includes(b.pace))unsupported.push('темп: relaxed / standard');
  if(!['ru','en'].includes(b.guide_language))unsupported.push('язык гида: ru / en');
  if(b.interests.some(x=>!['museums','architecture'].includes(x)))unsupported.push('интересы каталога: museums / architecture');
  if((b.must_have||[]).length||(b.avoid||[]).length)unsupported.push('индивидуальные обязательные/запрещённые объекты требуют проверки менеджером');
