    const date=iso(Date.parse(b.start_date)+86400000*i),slots=[];
    if(i===0){slots.push({start:'08:00',end:'12:00',kind:'transport',title:'Сапсан (РЖД): Москва, Ленинградский вокзал → Санкт-Петербург, Московский вокзал'},{start:'12:00',end:'13:00',kind:'transfer',title:'Метро/такси от Московского вокзала до отеля, резерв'},{start:'13:00',end:'15:00',kind:'rest',title:'Обед, отдых, заселение с 14:00'});}
    else slots.push({start:'09:00',end:'10:00',kind:'rest',title:'Завтрак и свободное время'});
    if(i===n-1){slots.push({start:'10:00',end:'11:00',kind:'rest',title:'Выселение, хранение багажа'},{start:'12:00',end:'14:00',kind:'activity',title:b.interests.includes('architecture')?'Прогулка: Дворцовая площадь, Исаакиевский собор, Медный всадник':(new Date(date).getUTCDay()===1?'Русский музей (Инженерная ул., 4)':'Государственный Эрмитаж (Дворцовая наб., 34)'),opening:'10:00–18:00'},{start:'14:00',end:'16:00',kind:'rest',title:'Обед, багаж, резерв'},{start:'16:00',end:'17:00',kind:'transfer',title:'Метро/такси до Московского вокзала'},{start:'18:00',end:'22:00',kind:'transport',title:'Сапсан (РЖД): Санкт-Петербург, Московский вокзал → Москва, Ленинградский вокзал'});}
    else if(i===0)slots.push({start:'15:00',end:'17:00',kind:'activity',title:b.interests.includes('museums')?(new Date(date).getUTCDay()===1?'Русский музей с гидом (Инженерная ул., 4)':'Государственный Эрмитаж с гидом (Дворцовая наб., 34)'):'Архитектурная прогулка с гидом: Невский проспект, Казанский собор, Спас на Крови',opening:'10:00–18:00'});
    else slots.push({start:'10:00',end:b.pace==='relaxed'?'12:00':'13:00',kind:'free',title:'Свободная прогулка: '+b.interests.join(', ')+' (идеи: Петропавловская крепость, Новая Голландия, Летний сад)'},{start:'13:00',end:'18:00',kind:'rest',title:'Обед и свободное время. Платные услуги не включены.'});
    return {date,city:'Санкт-Петербург',slots};
  });
  for(const day of c.s.itinerary)for(let i=1;i<day.slots.length;i++)if(day.slots[i].start<day.slots[i-1].end)return stop(c,'MANAGER_REVIEW','Конфликт расписания');
  c.s.feasibility={mock:true,calendar:'synthetic daily opening 10–18',transport:'synthetic timetable',time_conflicts:0,free_days:n-2};
  return c;
}
function sg4(c){
  if(c.halt||!c.planning)return c;
  trace(c,'SG4','filter and rank fixture services');
  const b=c.s.brief;
  const hotels=[{id:'H3-VEDENSKY',name:'Hotel Vedensky (3★), Санкт-Петербург',stars:3,night:4000,rating:4.5,center_minutes:20},{id:'H5-GRAND-EUROPE',name:'Гранд Отель Европа (5★), ул. Михайловская, 1/7',stars:5,night:15000,rating:4.9,center_minutes:10}];
  c.s.services={mock:true,transport:{id:'RZD-SAPSAN-RETURN',name:'Сапсан (РЖД): Москва ⇄ Санкт-Петербург, 2 кл./эконом, туда-обратно',departure:b.start_date,return:b.end_date,adult_fare:4000},hotel:hotels.filter(h=>h.stars>=b.hotel_stars).sort((a,b)=>a.night-b.night)[0],nights:days(b)-1,rooms:Math.ceil(b.adults/2),guide:{id:'DEMO-GUIDE-'+b.guide_language,language:b.guide_language,date:b.start_date,from:'15:00',to:'17:00',contact:'guide@example.test'},transfers:2,activities:2,selection_reason:'Meet mandatory stars; lowest synthetic price among matching hotels',shortlist:hotels.filter(h=>h.stars>=b.hotel_stars)};
  return c;
}
function sg5(c){
  if(c.halt)return c;
  const {e,s}=c;
  if(c.planning){
    trace(c,'SG5','exact arithmetic / budget gate / version proposal');
    const q=quote(s.brief);
    if(q.total>s.brief.budget_total){
      const cheaper=quote(s.brief,3);
      return ask(c,'NEEDS_RESOLUTION',`Демо-цена ${q.total} RUB превышает общий бюджет ${s.brief.budget_total} RUB. Что можно изменить?`,{conflicts:['BUDGET_VS_SERVICES'],calculation:q,alternatives:[{patch:{budget_total:q.total},description:'Увеличить бюджет, сохранить требования'},...(s.brief.hotel_stars===5?[{patch:{hotel_stars:3,budget_total:Math.max(s.brief.budget_total,cheaper.total)},description:`Отель 3 звезды: ${cheaper.total} RUB. Только после согласия клиента.`}]:[])]});
    }
    s.proposal_version++;
    s.proposal={version:s.proposal_version,brief_revision:s.revision,created_at:c.now,valid_until:new Date(Date.parse(c.now)+86400000).toISOString(),mock:true,calculation:q,itinerary:clone(s.itinerary),services:clone(s.services),includes:['Поезд туда/обратно','Отель','2 групповых трансфера','2 посещения','1 экскурсия с гидом'],excludes:['Питание','Страхование','Личные расходы','Дополнительные платные активности'],conditions:'DEMO, не оферта. Цена действует 24 часа. Отмена: только через менеджера.'};
    s.proposals.push(clone(s.proposal));
    return stop(c,'AWAITING_APPROVAL',`Предложение v${s.proposal_version}: ${q.total} RUB за всю группу. Подтвердите эту версию или измените требования.`,{proposal:s.proposal});
  }
  if(e.event==='approve'){
    trace(c,'SG5','explicit approval of current version');
