    say(c,'WAITING_TRAVELLERS','Предложение согласовано. Передайте тестовые данные всех туристов: full_name, birth_date, document_id.');
  }
  return c;
}
function sg6(c){
  if(c.halt)return c;
  const {e,s}=c;
  if(!['approve','travellers'].includes(e.event))return c;
  trace(c,'SG6','validate travellers / MOCK payment and bookings / quality');
  if(s.status!=='WAITING_TRAVELLERS')return reject(c,'Сначала согласуйте актуальное предложение.');
  if(!e.travellers)return stop(c,'WAITING_TRAVELLERS','Нужны тестовые данные всех туристов.');
  if(!Array.isArray(e.travellers)||e.travellers.length!==s.brief.adults)return stop(c,'WAITING_TRAVELLERS','Число карточек туристов должно совпадать с размером группы.');
  const ids=new Set();
  for(const t of e.travellers){
    if(typeof t.full_name!=='string'||t.full_name.trim().length<3||!validDate(t.birth_date)||typeof t.document_id!=='string'||!/^TEST-[A-Z0-9-]+$/.test(t.document_id))return stop(c,'WAITING_TRAVELLERS','Используйте полное имя, дату рождения и вымышленный document_id TEST-...');
    const adultCutoff=Number(s.brief.start_date.replaceAll('-',''))-180000;
    if(Number(t.birth_date.replaceAll('-',''))>adultCutoff||t.birth_date<'1900-01-01'||ids.has(t.document_id))return stop(c,'WAITING_TRAVELLERS','Нужны взрослые туристы и уникальные тестовые документы.');
    ids.add(t.document_id);
  }
  s.travellers=clone(e.travellers);
  s.documents={mock:true,contract_id:'DEMO-CONTRACT-'+s.request_id,invoice_id:'DEMO-INVOICE-'+s.request_id,amount:s.proposal.calculation.total,consent:'DEMO synthetic travellers only'};
  s.payment={status:'MOCK_SUCCESS',reference:'DEMO-PAY-'+s.request_id,amount:s.documents.amount,currency:'RUB'};
  s.bookings=['transport','hotel','activities','transfers','guide'].map(type=>({type,id:'DEMO-'+type.toUpperCase()+'-'+s.session_id,status:'MOCK_SUCCESS',proposal_version:s.approved_version,start_date:s.brief.start_date,end_date:s.brief.end_date}));
  s.qa={travellers_match:true,dates_match:s.bookings.every(x=>x.start_date===s.brief.start_date&&x.end_date===s.brief.end_date),versions_match:s.approved_version===s.proposal.version,paid:s.payment.amount===s.proposal.calculation.total,guide_assigned:!!s.services.guide,calendar_conflicts:s.feasibility.time_conflicts};
  if(!s.qa.dates_match||!s.qa.versions_match||!s.qa.paid||s.qa.calendar_conflicts)return stop(c,'MANAGER_REVIEW','Не пройдена финальная сверка.');
  say(c,'BOOKED','Демо-бронирования подтверждены.');return c;
}
function sg7(c){
  if(c.halt)return c;
  const {e,s}=c;
  if(s.status==='BOOKED'){
    trace(c,'SG7','assemble and return travel pack');
    const md=['# DEMO TRAVEL PACK',`Заказ ${s.request_id}; версия ${s.approved_version}`,`${s.brief.start_date} — ${s.brief.end_date}; ${s.brief.adults} взрослых`,...s.itinerary.flatMap(d=>[`## ${d.date}`,...d.slots.map(x=>`${x.start}–${x.end}: ${x.title}`)]),'## Подтверждения',...s.bookings.map(x=>`${x.type}: ${x.id} (${x.status})`),'## Контакты и инструкции',`Отель: ${s.services.hotel.name}; контакты и точный адрес — в подтверждении бронирования`,`DEMO гид: ${s.services.guide.contact}; встреча у входа в отель в 15:00 первого дня`,'Поддержка: support@example.test (вымышленный адрес)','Прибытие на Ленинградский вокзал (Москва) к отправлению Сапсана: минимум за 30 минут. По прибытии в Санкт-Петербург — метро или такси от Московского вокзала.','Названия отелей, музеев и поездов реальные, но бронирования, цены и расписание в демо-режиме ориентировочные: актуальные данные проверяйте у поставщиков.'].join('\n');
    s.travel_pack={mock:true,proposal_version:s.approved_version,markdown:md,documents:clone(s.documents),tickets_and_vouchers:clone(s.bookings),itinerary:clone(s.itinerary),contact:'support@example.test',delivery:'returned_in_webhook_response',received:false};
    return stop(c,'AWAITING_DOCUMENT_RECEIPT','Travel pack готов. Подтвердите получение событием ack_documents.',{travel_pack:s.travel_pack});
  }
  if(e.event==='ack_documents'){
    if(s.status!=='AWAITING_DOCUMENT_RECEIPT')return reject(c,'Нет пакета, ожидающего подтверждения.');
    s.travel_pack.received=true;return stop(c,'READY_FOR_TRIP','Получение документов подтверждено. Ожидается start_trip.');
  }
  if(e.event==='start_trip'){
    if(s.status!=='READY_FOR_TRIP')return reject(c,'Сначала подтвердите получение travel pack.');
    s.trip_started_at=c.now;return stop(c,'IN_TRIP','Поездка началась (событие учебного симулятора).');
  }
  if(e.event==='question'){
    if(!s.travel_pack)return reject(c,'Travel pack ещё не создан.');
    return stop(c,s.status,'Используйте актуальный travel pack. Индивидуальный вопрос передан менеджеру.',{travel_pack:s.travel_pack,manager_question:e.message||''});
  }
  if(e.event==='incident'){
    if(s.status!=='IN_TRIP')return reject(c,'Инцидент принимается во время поездки.');
    if(typeof e.message!=='string'||!e.message.trim())return reject(c,'Опишите инцидент.');
    const inc={id:'INC-'+(s.incidents.length+1),message:e.message,status:'OPEN',assignee:'manager',resolution:null,created_at:c.now};s.incidents.push(inc);
    return stop(c,'IN_TRIP','Инцидент зарегистрирован и передан менеджеру.',{incident:inc});
  }
  if(e.event==='resolve_incident'){
    const inc=s.incidents.find(x=>x.id===e.incident_id&&x.status==='OPEN');
    if(!inc||typeof e.resolution!=='string'||!e.resolution.trim())return reject(c,'Нужны открытый incident_id и решение менеджера.');
    inc.status='RESOLVED';inc.resolution=e.resolution;return stop(c,s.status,'Решение инцидента сохранено.');
  }
  return c;
}
function sg8(c){
  if(c.halt)return c;
  const {e,s}=c;
  if(e.event==='end_trip'){
    if(s.status!=='IN_TRIP')return reject(c,'Поездка ещё не началась.');
    s.trip_ended_at=c.now;trace(c,'SG8','trip ended / request feedback');
    return stop(c,'AWAITING_FEEDBACK','Оцените тур: CSAT 1–5, NPS 0–10, текст. Можно явно пропустить отзыв.');
